  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist,
   *the input card info and withdraw status
   *and number should be cleared*/
  ejectCard(): boolean {
    /*Definition Start*/
    let inputCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (o: any) =>
            l({
              logic: () => o.Password === this.PasswordValidated,
              description: "o.Password=PasswordValidated",
            })
              .and({
                logic: () => o.CardID === this.InputCard.CardID,
                description: "o.CardID=InputCard.CardID",
              })
              .build().pass,
        ),
      description:
        "BankCard.allInstance()->any(o|o.Password=PasswordValidatedando.CardID=InputCard.CardID)",
    }).build().pass;
    let isDeposit: boolean = l({
      logic: () => true,
      description: "true",
    }).build().pass;
    let cleared: boolean = l({
      logic: () => false,
      description: "false",
    }).build().pass;
    let isValid: boolean = l({
      logic: () => this.PasswordValidated,
      description: "PasswordValidated",
    })
      .and({
        logic: () => getRepository(ClassName).includes(inputCard),
        description: "ClassName.allInstance()->includes(inputCard)",
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(inputCard) === false,
        description: "inputCard.oclIsUndefined()=false",
      })
        .and({
          logic: () => this.PasswordValidated === true,
          description: "PasswordValidated=true",
        })
        .and({
          logic: () => getRepository(ClassName).includes(inputCard),
          description: "ClassName.allInstance()->includes(inputCard)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (cleared = true),
      description: "cleared=true",
    })
      .and({
        execute: () => isValid,
        description: "result=isValid",
      })
      .and({
        execute: () =>
          l({
            execute: () => this.PasswordValidated,
            description: "PasswordValidated",
          }).and({
            execute: () => getRepository(ClassName).push(inputCard),
            description: "ClassName.allInstance()->includes(inputCard)",
          }),
        description:
          "(PasswordValidatedandClassName.allInstance()->includes(inputCard))",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

